/* ===== header: include/wlr/types/wlr_linux_drm_syncobj_v1.h ===== */
/*
 * This an unstable interface of wlroots. No guarantees are made regarding the
 * future consistency of this API.
 */
#ifndef WLR_USE_UNSTABLE
#error "Add -DWLR_USE_UNSTABLE to enable unstable wlroots features"
#endif

#ifndef WLR_TYPES_WLR_LINUX_DRM_SYNCOBJ_V1_H
#define WLR_TYPES_WLR_LINUX_DRM_SYNCOBJ_V1_H

#include <wayland-server-core.h>

struct wlr_buffer;
struct wlr_surface;

struct wlr_linux_drm_syncobj_surface_v1_state {
	struct wlr_drm_syncobj_timeline *acquire_timeline;
	uint64_t acquire_point;

	struct {
		bool committed;
		struct wlr_drm_syncobj_timeline *release_timeline;
		uint64_t release_point;
		struct wlr_drm_syncobj_merger *release_merger;
	} WLR_PRIVATE;
};

struct wlr_linux_drm_syncobj_manager_v1 {
	struct wl_global *global;

	struct {
		int drm_fd;

		struct wl_listener display_destroy;
	} WLR_PRIVATE;
};

/**
 * Advertise explicit synchronization support to clients.
 *
 * The compositor must be prepared to handle fences coming from clients and to
 * send release fences correctly. In particular, both the renderer and the
 * backend need to support explicit synchronization.
 */
struct wlr_linux_drm_syncobj_manager_v1 *wlr_linux_drm_syncobj_manager_v1_create(
	struct wl_display *display, uint32_t version, int drm_fd);

struct wlr_linux_drm_syncobj_surface_v1_state *wlr_linux_drm_syncobj_v1_get_surface_state(
	struct wlr_surface *surface);

/**
 * Signal the release point when wlr_buffer.events.release is emitted.
 *
 * Compositors unwilling to track fine-grained commit release can call this
 * helper on surface commit.
 */
bool wlr_linux_drm_syncobj_v1_state_signal_release_with_buffer(
	struct wlr_linux_drm_syncobj_surface_v1_state *state, struct wlr_buffer *buffer);

/**
 * Register a release point for buffer usage.
 *
 * This function may be called multiple times for the same commit. The client's
 * release point will be signalled when all registered points are signalled, and
 * a new buffer has been committed.
 *
 * Because the given release point may not be materialized, a wl_event_loop must
 * be supplied to schedule a wait internally, if needed
 */
bool wlr_linux_drm_syncobj_v1_state_add_release_point(
	struct wlr_linux_drm_syncobj_surface_v1_state *state,
	struct wlr_drm_syncobj_timeline *release_timeline, uint64_t release_point,
	struct wl_event_loop *event_loop);

/**
 * Register the DMA-BUF release of a buffer for buffer usage.
 * Non-dmabuf buffers are considered to be immediately available (no wait).
 *
 * This function may be called multiple times for the same commit. The client's
 * release point will be signalled when all registered points are signalled, and
 * a new buffer has been committed.
 *
 * Because the platform may not support DMA-BUF fence merges, a wl_event_loop
 * must be supplied to schedule a wait internally, if needed
 *
 * Waits for write access
 */
bool wlr_linux_drm_syncobj_v1_state_add_release_from_implicit_sync(
	struct wlr_linux_drm_syncobj_surface_v1_state *state,
	struct wlr_buffer *buffer, struct wl_event_loop *event_loop);

#endif


/* ===== header: include/wlr/types/wlr_presentation_time.h ===== */
/*
 * This an unstable interface of wlroots. No guarantees are made regarding the
 * future consistency of this API.
 */
#ifndef WLR_USE_UNSTABLE
#error "Add -DWLR_USE_UNSTABLE to enable unstable wlroots features"
#endif

#ifndef WLR_TYPES_WLR_PRESENTATION_TIME_H
#define WLR_TYPES_WLR_PRESENTATION_TIME_H

#include <stdbool.h>
#include <stddef.h>
#include <wayland-server-core.h>

struct wlr_surface;

struct wlr_output;
struct wlr_output_event_present;

struct wlr_presentation {
	struct wl_global *global;

	struct {
		struct wl_signal destroy;
	} events;

	struct {
		struct wl_listener display_destroy;
	} WLR_PRIVATE;
};

struct wlr_presentation_feedback {
	struct wl_list resources; // wl_resource_get_link()

	// Only when the wlr_presentation_surface_textured_on_output() or
	// wlr_presentation_surface_scanned_out_on_output() helper has been called.
	struct wlr_output *output;
	bool output_committed;
	uint32_t output_commit_seq;
	bool zero_copy;

	struct {
		struct wl_listener output_commit;
		struct wl_listener output_present;
		struct wl_listener output_destroy;
	} WLR_PRIVATE;
};

struct wlr_presentation_event {
	struct wlr_output *output;
	uint64_t tv_sec;
	uint32_t tv_nsec;
	uint32_t refresh;
	uint64_t seq;
	uint32_t flags; // enum wp_presentation_feedback_kind
};

struct wlr_backend;

struct wlr_presentation *wlr_presentation_create(struct wl_display *display,
	struct wlr_backend *backend, uint32_t version);
/**
 * Mark the current surface's buffer as sampled.
 *
 * The compositor must call this function when it uses the surface's current
 * contents (e.g. when rendering the surface's current texture, when
 * referencing its current buffer, or when directly scanning out its current
 * buffer). A wlr_presentation_feedback is returned. The compositor should call
 * wlr_presentation_feedback_send_presented() if this content has been displayed,
 * then wlr_presentation_feedback_destroy().
 *
 * NULL is returned if the client hasn't requested presentation feedback for
 * this surface.
 */
struct wlr_presentation_feedback *wlr_presentation_surface_sampled(
	struct wlr_surface *surface);
void wlr_presentation_feedback_send_presented(
	struct wlr_presentation_feedback *feedback,
	const struct wlr_presentation_event *event);
void wlr_presentation_feedback_destroy(
	struct wlr_presentation_feedback *feedback);

/**
 * Fill a wlr_presentation_event from a struct wlr_output_event_present.
 */
void wlr_presentation_event_from_output(struct wlr_presentation_event *event,
		const struct wlr_output_event_present *output_event);

/**
 * Mark the current surface's buffer as textured on the given output.
 *
 * Instead of calling wlr_presentation_surface_sampled() and managing the
 * struct wlr_presentation_feedback itself, the compositor can call this function
 * before a wlr_output_commit_state() call to indicate that the surface's current
 * contents have been copied to a buffer which will be displayed on the output.
 */
void wlr_presentation_surface_textured_on_output(struct wlr_surface *surface,
	struct wlr_output *output);
/**
 * Mark the current surface's buffer as scanned out on the given output.
 *
 * Same as wlr_presentation_surface_textured_on_output(), but indicates direct
 * scan-out.
 */
void wlr_presentation_surface_scanned_out_on_output(struct wlr_surface *surface,
	struct wlr_output *output);

#endif


