/**
 * @ingroup iface_zwp_linux_dmabuf_v1
 * @struct zwp_linux_dmabuf_v1_interface
 */
struct zwp_linux_dmabuf_v1_interface {
	/**
	 * unbind the factory
	 *
	 * Objects created through this interface, especially wl_buffers,
	 * will remain valid.
	 */
	void (*destroy)(struct wl_client *client,
			struct wl_resource *resource);
	/**
	 * create a temporary object for buffer parameters
	 *
	 * This temporary object is used to collect multiple dmabuf
	 * handles into a single batch to create a wl_buffer. It can only
	 * be used once and should be destroyed after a 'created' or
	 * 'failed' event has been received.
	 * @param params_id id for the newly created zwp_linux_buffer_params_v1
	 */
	void (*create_params)(struct wl_client *client,
			      struct wl_resource *resource,
			      uint32_t params_id);
	/**
	 * get default feedback
	 *
	 * This request creates a new zwp_linux_dmabuf_feedback_v1 object
	 * not bound to a particular surface. This object will deliver
	 * feedback about dmabuf parameters to use if the client doesn't
	 * support per-surface feedback (see get_surface_feedback).
	 * @since 4
	 */
	void (*get_default_feedback)(struct wl_client *client,
				     struct wl_resource *resource,
				     uint32_t id);
	/**
	 * get feedback for a surface
	 *
	 * This request creates a new zwp_linux_dmabuf_feedback_v1 object
	 * for the specified wl_surface. This object will deliver feedback
	 * about dmabuf parameters to use for buffers attached to this
	 * surface.
	 *
	 * If the surface is destroyed before the
	 * zwp_linux_dmabuf_feedback_v1 object, the feedback object becomes
	 * inert.
	 * @since 4
	 */
	void (*get_surface_feedback)(struct wl_client *client,
				     struct wl_resource *resource,
				     uint32_t id,
				     struct wl_resource *surface);
};

