static void WLR_types_wlr_color_management_v1_c_cm_output_handle_get_image_description(struct wl_client *client,
		struct wl_resource *cm_output_resource, uint32_t id) {
	struct wlr_color_management_output_v1 *cm_output = WLR_types_wlr_color_management_v1_c_cm_output_from_resource(cm_output_resource);
	if (cm_output == NULL) {
		WLR_types_wlr_color_management_v1_c_image_desc_create_failed(cm_output_resource, id,
			WP_IMAGE_DESCRIPTION_V1_CAUSE_NO_OUTPUT,
			"output has been destroyed");
		return;
	}

	struct wlr_image_description_v1_data data = {
		.tf_named = WP_COLOR_MANAGER_V1_TRANSFER_FUNCTION_GAMMA22,
		.primaries_named = WP_COLOR_MANAGER_V1_PRIMARIES_SRGB,
	};
	const struct wlr_output_image_description *image_desc = cm_output->output->image_description;
	if (image_desc != NULL) {
		data.tf_named = wlr_color_manager_v1_transfer_function_from_wlr(image_desc->transfer_function);
		data.primaries_named = wlr_color_manager_v1_primaries_from_wlr(image_desc->primaries);
	}
	WLR_types_wlr_color_management_v1_c_image_desc_create_ready(cm_output->manager, cm_output_resource, id, &data, true);
}

